CREATE TABLE IF NOT EXISTS src_erp.erp_invoice(id BIGINT AUTO_INCREMENT PRIMARY KEY,invoice_no VARCHAR(32) NOT NULL UNIQUE,sales_order_no VARCHAR(32),customer_code VARCHAR(32) NOT NULL,invoice_date DATE,amount DECIMAL(18,2) NOT NULL,tax_amount DECIMAL(18,2) DEFAULT 0,status VARCHAR(16) DEFAULT 'APPLIED',created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS src_erp.erp_receipt(id BIGINT AUTO_INCREMENT PRIMARY KEY,receipt_no VARCHAR(32) NOT NULL UNIQUE,customer_code VARCHAR(32) NOT NULL,bank_reference VARCHAR(64),receipt_date DATE NOT NULL,amount DECIMAL(18,2) NOT NULL,unapplied_amount DECIMAL(18,2) NOT NULL,status VARCHAR(16) DEFAULT 'UNAPPLIED',created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS src_erp.erp_settlement(id BIGINT AUTO_INCREMENT PRIMARY KEY,settlement_no VARCHAR(32) NOT NULL,receipt_id BIGINT NOT NULL,receivable_id BIGINT NOT NULL,amount DECIMAL(18,2) NOT NULL,settled_by VARCHAR(32),settled_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uk_settlement(settlement_no,receivable_id));
ALTER TABLE src_erp.erp_receivable ADD COLUMN settled_amount DECIMAL(18,2) NOT NULL DEFAULT 0,ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'OPEN';
CREATE TABLE IF NOT EXISTS src_erp.erp_payable(id BIGINT AUTO_INCREMENT PRIMARY KEY,payable_no VARCHAR(32) NOT NULL UNIQUE,supplier_code VARCHAR(32) NOT NULL,source_order_no VARCHAR(32),amount DECIMAL(18,2) NOT NULL,paid_amount DECIMAL(18,2) DEFAULT 0,due_date DATE,status VARCHAR(16) DEFAULT 'OPEN',created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS src_erp.erp_order_cost(id BIGINT AUTO_INCREMENT PRIMARY KEY,sales_order_no VARCHAR(32) NOT NULL,cost_type VARCHAR(20) NOT NULL,cost_center_code VARCHAR(32),amount DECIMAL(18,2) NOT NULL,source_no VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_cost_order(sales_order_no));
